            { "Perfect Photo", "Foto perfecta" },
            { "Photo frames, screens and custom-photo furniture can render blank/white — either the game's own 100-item texture cache evicting mid-session (Purge + raise capacity below help), or the furniture setting above streaming in too many at once and overwhelming downloads. If Purge doesn't help, try lowering furniture draw distance/count first.", "Los marcos de fotos, pantallas y muebles con fotos personalizadas pueden verse en blanco — o la caché de texturas de 100 elementos del juego se vacía a mitad de sesión (Purgar + subir la capacidad abajo ayudan), o el ajuste de muebles de arriba carga demasiados a la vez y satura las descargas. Si Purgar no ayuda, prueba primero a bajar la distancia/cantidad de muebles." },
