            { "Players, NPCs, animals, collectables stay visible further away. Capped by the server's sync range — some entities cannot appear beyond it.", "Jugadores, NPC, animales y coleccionables siguen visibles a más distancia. Limitado por el rango de sincronización del servidor — algunas entidades no pueden aparecer más allá." },
            { "Props with the game's custom mesh-swap LOD keep their high-poly mesh at any distance. May raise VRAM/CPU load.", "Los objetos con el LOD de cambio de malla propio del juego conservan su malla de alto detalle a cualquier distancia. Puede aumentar la carga de VRAM/CPU." },
