            { "Sets the game's PC_LODBIAS quality value (trees, rocks, grass, terrain chunks) — higher holds high-poly meshes further out; 10 is the engine default. Terrain chunks bake this at load time, so islands and cliffs near your spawn only get the full value with the checkbox above.", "Establece el valor de calidad PC_LODBIAS del juego (árboles, rocas, hierba, fragmentos de terreno) — cuanto más alto, más lejos se mantienen las mallas de alto detalle; 10 es el valor del motor. Los fragmentos de terreno lo fijan al cargar, así que las islas y acantilados cerca de tu spawn solo reciben el valor completo con la casilla de arriba." },
