            { "Farming, gathering, teleport, radar, bag tools, and other QoL helpers — from one in-game menu. Press Insert to open it.", "Granja, recolección, teletransporte, radar, herramientas de bolsa y otras ayudas de calidad de vida — todo desde un único menú en el juego. Pulsa Insert para abrirlo." },
