            { "Disclaimer", "Aviso legal" },
            { "For educational and research use only. Use at your own risk; you are responsible for any account actions taken by the game operator.", "Solo para uso educativo y de investigación. Úsalo bajo tu propio riesgo; eres responsable de cualquier acción sobre tu cuenta por parte del operador del juego." },
