            { "Photo frames, screens and custom-photo furniture can render blank/white — either the game's own 100-item texture cache evicting mid-session (Purge + raise capacity below help), or the furniture setting above streaming in too many at once and overwhelming downloads. If Purge doesn't help, try lowering furniture draw distance/count first.", "相框、屏幕和自定义照片家具可能显示为空白/白色——要么是游戏自带的 100 项纹理缓存在游戏中被挤出（下方的“清空 + 提升容量”有帮助），要么是上方的家具设置一次流入太多、压垮下载。若清空无效，请先调低家具绘制距离/数量。" },
