            { "Finds every SANRIO gacha machine around you and pins it on the game map: the three event machines in Star Town plus machines placed by players in their homes (found while you roam; remembered for the session). Touching each machine drops a capsule reward once per day — up to 5 per day.", "Encontra todas as máquinas de gacha SANRIO ao seu redor e as fixa no mapa do jogo: as três máquinas do evento em Star Town mais as colocadas por jogadores em suas casas (encontradas enquanto você anda; lembradas durante a sessão). Tocar em cada máquina solta uma cápsula de recompensa uma vez por dia — até 5 por dia." },
