            { "Pause Teleport On Eat / Repair", "Pausar teleporte ao comer / reparar" },
            { "Perfect Photo", "Foto Perfeita" },
            { "Photo frames, screens and custom-photo furniture can render blank/white — either the game's own 100-item texture cache evicting mid-session (Purge + raise capacity below help), or the furniture setting above streaming in too many at once and overwhelming downloads. If Purge doesn't help, try lowering furniture draw distance/count first.", "Molduras de fotos, telas e móveis com fotos personalizadas podem renderizar em branco — ou o cache de texturas de 100 itens do jogo despeja no meio da sessão (Limpar + aumentar a capacidade abaixo ajudam), ou a configuração de móveis acima carrega demais de uma vez e sobrecarrega os downloads. Se Limpar não ajudar, tente primeiro reduzir a distância/quantidade de móveis." },
