            { "Player, camera and input", "Jogador, câmera e entrada" },
            { "Players, NPCs, animals, collectables stay visible further away. Capped by the server's sync range — some entities cannot appear beyond it.", "Jogadores, NPCs, animais e coletáveis ficam visíveis mais longe. Limitado pelo alcance de sincronização do servidor — algumas entidades não podem aparecer além dele." },
            { "Props with the game's custom mesh-swap LOD keep their high-poly mesh at any distance. May raise VRAM/CPU load.", "Objetos com o LOD de troca de malha do jogo mantêm a malha de alta poligonagem a qualquer distância. Pode aumentar a carga de VRAM/CPU." },
