            { "Sets the game's PC_LODBIAS quality value (trees, rocks, grass, terrain chunks) — higher holds high-poly meshes further out; 10 is the engine default. Terrain chunks bake this at load time, so islands and cliffs near your spawn only get the full value with the checkbox above.", "Define o valor de qualidade PC_LODBIAS do jogo (árvores, rochas, grama, blocos de terreno) — quanto maior, mais longe as malhas de alta poligonagem são mantidas; 10 é o padrão do motor. Blocos de terreno fixam isso ao carregar, então ilhas e penhascos perto do seu spawn só recebem o valor completo com a caixa acima." },
