            { "Photo frames, screens and custom-photo furniture can render blank/white — either the game's own 100-item texture cache evicting mid-session (Purge + raise capacity below help), or the furniture setting above streaming in too many at once and overwhelming downloads. If Purge doesn't help, try lowering furniture draw distance/count first.", "กรอบรูป จอ และเฟอร์นิเจอร์รูปถ่ายอาจแสดงเป็นสีขาว/ว่าง — อาจเป็นเพราะแคชเท็กซ์เจอร์ 100 รายการของเกมถูกเคลียร์กลางเซสชัน (กดล้าง + เพิ่มความจุด้านล่างช่วยได้) หรือการตั้งค่าเฟอร์นิเจอร์ด้านบนสตรีมเข้ามามากเกินจนดาวน์โหลดไม่ทัน ถ้าล้างแล้วไม่ช่วย ลองลดระยะ/จำนวนเฟอร์นิเจอร์ก่อน" },
