            { "Players, NPCs, animals, collectables stay visible further away. Capped by the server's sync range — some entities cannot appear beyond it.", "ผู้เล่น NPC สัตว์ และของเก็บได้จะมองเห็นได้ไกลขึ้น ถูกจำกัดด้วยระยะซิงก์ของเซิร์ฟเวอร์ — บางเอนทิตีไม่สามารถปรากฏเกินระยะนั้น" },
