            { "Distance quality reduction disabled (full detail).", "거리에 따른 품질 저하를 껐습니다 (전체 디테일)." },
            { "Distant low-poly scenery (rocks, islands, scene chunks) swaps to full-detail geometry much further away. Covers both HLOD proxies and the base-scene chunk streamer; applies live, no reload.", "멀리 있는 저폴리 배경 (바위, 섬, 지형 조각)이 훨씬 먼 거리에서도 완전한 형태로 바뀝니다. HLOD 프록시와 기본 씬 스트리머 양쪽에 적용되며, 재접속 없이 즉시 반영됩니다." },
