            { "Finds every SANRIO gacha machine around you and pins it on the game map: the three event machines in Star Town plus machines placed by players in their homes (found while you roam; remembered for the session). Touching each machine drops a capsule reward once per day — up to 5 per day.", "주변의 모든 SANRIO 뽑기 기계를 찾아 게임 지도에 고정합니다: 별빛 마을의 이벤트 기계 3대와 플레이어가 집에 설치한 기계 (돌아다니며 발견하고 세션 동안 기억합니다). 기계마다 하루 한 번 캡슐 보상을 주며, 하루 최대 5개입니다." },
