            { "Perfect Photo", "완벽한 포착" },
            { "Photo frames, screens and custom-photo furniture can render blank/white — either the game's own 100-item texture cache evicting mid-session (Purge + raise capacity below help), or the furniture setting above streaming in too many at once and overwhelming downloads. If Purge doesn't help, try lowering furniture draw distance/count first.", "액자, 스크린, 사진 가구가 비어 보이거나 하얗게 나올 수 있습니다 — 게임 자체의 100개짜리 텍스처 캐시가 도중에 비워졌거나, 위의 가구 설정이 한 번에 너무 많이 불러와 다운로드가 밀린 경우입니다. 캐시 비우기와 용량 늘리기가 도움이 되지 않으면 가구 시야 거리/개수부터 낮춰 보세요." },
