            { "Player, camera and input", "캐릭터, 카메라, 입력" },
            { "Players, NPCs, animals, collectables stay visible further away. Capped by the server's sync range — some entities cannot appear beyond it.", "플레이어, NPC, 동물, 수집물이 더 멀리서도 보입니다. 서버 동기화 범위가 상한이라 그 밖의 엔티티는 나타날 수 없습니다." },
            { "Props with the game's custom mesh-swap LOD keep their high-poly mesh at any distance. May raise VRAM/CPU load.", "메시 교체 LOD를 쓰는 게임 소품이 거리와 관계없이 고폴리 메시를 유지합니다. VRAM/CPU 부하가 늘 수 있습니다." },
